// A workflow is the task: typed steps, written by a human or generated by an LLM, compiled, then frozen.
//
//   export default workflow(project, "Players can fire homing missiles", ({ step, design, review, expect }) => {
//     const designed = design("Missile design is written", { produces: ["docs/missiles.md"] })
//     const hud = step("Player sees lock-on", { after: [designed], skip: [{ rule: deterministicSim, why: "Presentation only" }] })
//     review("Owner approves", { after: [hud] })
//   })
import type { AnyArea, AreaChange } from "./area.ts"
import type { Intent } from "./facts.ts"
import type { AnyRule } from "./rule.ts"
import type { Project } from "./project.ts"
import { scopedExpect, type AnyExpectation, type Expect, type Expectation } from "./expect.ts"

export interface Skip {
  readonly rule: AnyRule
  /** Recorded in the ledger as a waiver; needs human approval. */
  readonly why: string
}

export interface StepOptions<P extends string> {
  readonly after?: readonly Step[]
  /** Forecast of what the step will touch; the actual diff still decides what is owed. */
  readonly expects?: readonly (AnyArea | AreaChange)[]
  readonly mustNotTouch?: readonly AnyArea[]
  readonly skip?: readonly Skip[]
  /** Extra expectations that close this step, beyond what the rules require. */
  readonly done?: readonly Expectation<P>[]
  readonly produces?: readonly string[]
}

export interface Step {
  readonly kind: "step"
  readonly id: string
  readonly title: string
  readonly intent: Intent
  readonly after: readonly Step[]
  readonly expects: readonly (AnyArea | AreaChange)[]
  readonly mustNotTouch: readonly AnyArea[]
  readonly skip: readonly Skip[]
  readonly done: readonly AnyExpectation[]
  readonly produces: readonly string[]
}

type StepFn<P extends string> = (title: string, opts?: StepOptions<P>) => Step

export interface WorkflowContext<P extends string> {
  readonly step: StepFn<P>
  readonly design: StepFn<P>
  readonly fix: StepFn<P>
  readonly refactor: StepFn<P>
  readonly optimize: StepFn<P>
  readonly review: StepFn<P>
  /** Only proofs this project can prove are accepted here. The runner runs them when the step closes. */
  readonly expect: Expect<P>
}

export interface Workflow {
  readonly kind: "workflow"
  readonly title: string
  readonly project: Project
  readonly steps: readonly Step[]
}

const slug = (title: string) =>
  title
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "")

export function workflow<P extends string>(project: Project<P>, title: string, body: (ctx: WorkflowContext<P>) => void): Workflow {
  const steps: Step[] = []
  const make =
    (intent: Intent): StepFn<P> =>
    (title, opts = {}) => {
      const id = slug(title)
      if (steps.some((s) => s.id === id)) throw new Error(`workflow "${title}": duplicate step "${id}"`)
      const step: Step = {
        kind: "step",
        id,
        title,
        intent,
        after: opts.after ?? [],
        expects: opts.expects ?? [],
        mustNotTouch: opts.mustNotTouch ?? [],
        skip: opts.skip ?? [],
        done: opts.done ?? [],
        produces: opts.produces ?? [],
      }
      steps.push(step)
      return step
    }
  body({
    step: make("change"),
    design: make("design"),
    fix: make("fix"),
    refactor: make("refactor"),
    optimize: make("optimize"),
    review: make("review"),
    expect: scopedExpect({
      slots: [],
      runner: undefined,
      signal: new AbortController().signal,
      context: { rule: undefined, item: undefined },
    }),
  })
  return { kind: "workflow", title, project, steps }
}
